with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الهيدرولوجيا الجوية والتنبؤ بالفيضانات','دورة الماء الجوية والتحويل من الهطول إلى الجريان، ونمذجة الأحواض والرصد الهيدرومتري والتنبؤ بالفيضانات والإنذار المبكر.',58,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الماء الجوي والتحول من المطر إلى الجريان',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'النمذجة والرصد والتنبؤ بالفيضانات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('atmospheric-water-budget','ميزانية الماء في الغلاف الجوي','مصادر بخار الماء ومصارفه وتغير المخزون','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"توازن بخار الماء بين التبخر والنتح والنقل الأفقي والتكاثف والهطول والتغير في التخزين الجوي. تُحلل الميزانية مكانياً وزمنياً مع مراعاة أن الفيض الرطوبي قد يختلف عن الهطول المحلي."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"ميزانية الماء في الغلاف الجوي","text":"احسب تغير مخزون بخار الماء في فترة افتراضية من فروق التدفقات والهطول. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"احسب تغير مخزون بخار الماء في فترة افتراضية من فروق التدفقات والهطول."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"ميزانية الماء ليست مساواة بين مطر المنطقة وتبخرها فقط؛ النقل عبر حدود المنطقة عنصر أساسي."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7760,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('evapotranspiration-estimation','تقدير التبخر والنتح','الطرق الفيزيائية والمرجعية وموازنة الطاقة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل التبخر والنتح انتقال الماء من السطح والغطاء النباتي إلى الجو. تتباين طرق التقدير بين القياس المباشر وموازنة الطاقة والطرق المناخية المرجعية، ولكل طريقة متطلبات بيانات وافتراضات."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تقدير التبخر والنتح","text":"قارن تقدير التبخر والنتح المرجعي مع تقدير مبني على موازنة الطاقة لموقع زراعي. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن تقدير التبخر والنتح المرجعي مع تقدير مبني على موازنة الطاقة لموقع زراعي."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"لا تساوِ بين التبخر المقاس من حوض مائي والتبخر-النتح الفعلي لسطح نباتي."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7770,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('precipitation-runoff-coupling','الاقتران بين الهطول والجريان','تحويل المطر إلى استجابة هيدرولوجية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتحكم شدة الهطول ومدته وتوزيعه المكاني ورطوبة التربة والغطاء الأرضي في الجزء الذي يتحول إلى جريان سطحي أو تسرب. تتغير العلاقة مع حالة الحوض قبل العاصفة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الاقتران بين الهطول والجريان","text":"حلل عاصفتين متساويتين في مجموع المطر ومختلفتين في الشدة والتوزيع. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل عاصفتين متساويتين في مجموع المطر ومختلفتين في الشدة والتوزيع."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"مجموع المطر وحده لا يحدد حجم الجريان أو توقيته."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7780,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('watershed-delineation','تحديد أحواض التصريف','الحدود الطبوغرافية وشبكة المجاري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحدد حوض التصريف المساحة التي تجمع المياه نحو مخرج محدد. تستخدم نماذج الارتفاع الرقمية واتجاهات الجريان وتراكمه لاشتقاق الحدود والشبكة، مع فحص أثر الدقة والطرق والمنشآت."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحديد أحواض التصريف","text":"أنشئ مخططاً مفاهيمياً لحوض ومخرج وخط تقسيم مياه وروافد. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ مخططاً مفاهيمياً لحوض ومخرج وخط تقسيم مياه وروافد."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"أخطاء نموذج الارتفاع أو معالجة المنخفضات قد تغير حدود الحوض."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7790,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('soil-moisture-antecedent-conditions','رطوبة التربة السابقة للعاصفة','أثر التشبع والعجز المائي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحدد رطوبة التربة السابقة مقدار السعة المتاحة للتخزين والتسرب. قد تنتج العاصفة نفسها استجابة مختلفة بعد فترة جافة مقارنة بفترة رطبة، كما تختلف الرطوبة رأسياً وبين أنواع التربة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"رطوبة التربة السابقة للعاصفة","text":"قارن سيناريوهين لعاصفة واحدة فوق تربة جافة وأخرى قريبة من التشبع. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن سيناريوهين لعاصفة واحدة فوق تربة جافة وأخرى قريبة من التشبع."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"ينبغي عدم استخدام قراءة رطوبة سطحية واحدة لتمثيل كامل عمق منطقة الجذور."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7800,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('infiltration-capacity','سعة التسرب وتغيرها أثناء العاصفة','النفاذية والتشبع والقشرة السطحية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف سعة التسرب معدل دخول الماء إلى التربة، وتتأثر بالنسيج والبنية والرطوبة الأولية والانضغاط والغطاء. عندما تتجاوز شدة المطر السعة المتاحة قد يتولد جريان فائض الشدة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"سعة التسرب وتغيرها أثناء العاصفة","text":"ارسم تغير سعة التسرب مع الزمن وقارنه بشدة مطر متغيرة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم تغير سعة التسرب مع الزمن وقارنه بشدة مطر متغيرة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"قيمة النفاذية المخبرية لا تمثل بالضرورة السلوك الحقلي لكل الحوض."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7810,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
