('rainfall-runoff-model-structure','بنية نماذج المطر والجريان','المدخلات والحالات والمعاملات والمخرجات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتكون النماذج المفاهيمية أو الفيزيائية من تمثيل اعتراض المطر والتسرب والتخزين والتحويل إلى جريان. يعتمد اختيار البنية على هدف التنبؤ وتوفر البيانات ومقياس الحوض."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"بنية نماذج المطر والجريان","text":"صمم مخطط تدفق يربط المطر الفعال بالتخزين والجريان الأساسي والسطحي. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مخطط تدفق يربط المطر الفعال بالتخزين والجريان الأساسي والسطحي."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"زيادة تعقيد النموذج لا تضمن تحسناً إذا كانت البيانات غير كافية."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7840,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('hydrological-model-calibration','معايرة النماذج الهيدرولوجية','تقدير المعاملات وفصل المعايرة عن التحقق','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تضبط المعايرة معاملات النموذج باستخدام مشاهدات الجريان، بينما يختبر التحقق أداءه على فترة مستقلة. يجب فحص أكثر من مقياس أداء وتجنب الإفراط في الملاءمة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"معايرة النماذج الهيدرولوجية","text":"اقترح تقسيم سلسلة زمنية إلى فترات معايرة وتحقق مع تبرير الاختيار. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح تقسيم سلسلة زمنية إلى فترات معايرة وتحقق مع تبرير الاختيار."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"الأداء الجيد في فترة المعايرة لا يثبت قابلية التنبؤ في ظروف مختلفة."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7850,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'الماء الجوي والتحول من المطر إلى الجريان'),
('hydrological-forecast-uncertainty','عدم اليقين في التنبؤ الهيدرولوجي','مصادر الخطأ والمنتجات الاحتمالية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ عدم اليقين من توقع المطر والقياسات والمعاملات وبنية النموذج والظروف الابتدائية. يمكن تمثيله بمجموعات سيناريوهات أو توزيعات احتمالية بدلاً من قيمة وحيدة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"عدم اليقين في التنبؤ الهيدرولوجي","text":"فسر نطاقاً افتراضياً لتوقع التصريف وحدد ما يعنيه للمستخدم التشغيلي. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر نطاقاً افتراضياً لتوقع التصريف وحدد ما يعنيه للمستخدم التشغيلي."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"لا تفسر حدود النطاق الاحتمالي كضمان لاحتواء النتيجة."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7860,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('flash-flood-meteorological-triggers','المحفزات الجوية للسيول المفاجئة','شدة المطر ومدة الهطول والتنظيم العاصفي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحدث الاستجابة السريعة عندما تتجاوز معدلات المطر قدرة التسرب والتخزين والتصريف، خصوصاً في الأحواض الصغيرة أو الحضرية. يتطلب التشخيص الجمع بين الرادار والمقاييس المطرية والتحليل التضاريسي."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"المحفزات الجوية للسيول المفاجئة","text":"حلل كيف يؤدي تمركز المطر مكانياً إلى اختلاف الخطر بين أحواض متجاورة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل كيف يؤدي تمركز المطر مكانياً إلى اختلاف الخطر بين أحواض متجاورة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"التنبيه الجوي لا يساوي قياساً مباشراً للتصريف أو عمق المياه."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمن