('urban-flood-runoff','الجريان والفيضانات في المدن','الأسطح غير المنفذة وشبكات التصريف','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تزيد الأسطح غير المنفذة سرعة الجريان وتقلل التسرب، بينما تؤثر سعة المصارف والأنفاق والانسدادات والتمدد العمراني في تجمع المياه. تتطلب النمذجة تمثيل البنية الحضرية."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الجريان والفيضانات في المدن","text":"قارن حوضاً طبيعياً وآخر حضرياً لهما مساحة ومطر متشابهان. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن حوضاً طبيعياً وآخر حضرياً لهما مساحة ومطر متشابهان."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"لا يكفي نموذج تضاريس عام لتمثيل تفاصيل الأرصفة والعبارات والمصارف."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7880,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('radar-rainfall-hydrology','استخدام تقديرات الرادار المطرية هيدرولوجياً','التحويل إلى مطر سطحي وتصحيح الانحياز','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يوفر الرادار توزيعاً مكانياً عالي التواتر للهطول، لكنه يتأثر بعلاقة الانعكاسية بالمطر والتوهين والحجب والارتفاع عن السطح. يلزم دمجه مع مقاييس المطر والتحقق من الانحياز."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"استخدام تقديرات الرادار المطرية هيدرولوجياً","text":"صمم إجراء مقارنة بين تراكم الرادار والمقاييس الأرضية على شبكة مشتركة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم إجراء مقارنة بين تراكم الرادار والمقاييس الأرضية على شبكة مشتركة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"لا تعتبر منتج الرادار قياساً أرضياً خالياً من الخطأ."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7890,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('satellite-precipitation-hydrology','تقديرات الأقمار الصناعية للهطول','التغطية الواسعة والدقة الزمنية والمكانية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تساعد منتجات الأقمار الصناعية على سد فجوات الرصد، خصوصاً في المناطق النائية، لكن دقتها تختلف حسب نوع المستشعر والسطح والموسم وشدة المطر. ينبغي تقييمها محلياً قبل استخدامها التشغيلي."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تقديرات الأقمار الصناعية للهطول","text":"قارن منتجاً فضائياً مع محطات مرجعية عبر مواسم مختلفة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن منتجاً فضائياً مع محطات مرجعية عبر مواسم مختلفة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"المتوسط الإقليمي قد يخفي أخطاء محلية مهمة في الأحواض الصغيرة."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7900,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('hydrometric-network-design','تصميم شبكة الرصد الهيدرومتري','مقاييس المطر والمناسيب والتصريف','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع الشبكة الفعالة بين رصد المطر ومناسيب الأنهار وقياسات التصريف ومعلومات تشغيل المنشآت. يعتمد توزيع المحطات على تمثيل الأحواض ومصادر الخطر واستمرارية الاتصال والصيانة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تصميم شبكة الرصد الهيدرومتري","text":"اقترح شبكة مراقبة لحوض افتراضي وحدد وظيفة كل محطة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح شبكة مراقبة لحوض افتراضي وحدد وظيفة كل محطة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"كثرة المحطات لا تعوض سوء التوزيع أو ضعف المعايرة والاتصال."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7910,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('stage-discharge-rating-curves','منحنيات العلاقة بين المنسوب والتصريف','القياس والمعايرة وتغير المجرى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحوّل منحنى المنسوب-التصريف قراءة المنسوب إلى تقدير للتصريف بناءً على قياسات ميدانية. قد يتغير المنحنى بسبب الترسيب والنحر والنباتات والمنشآت والفيضانات."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"منحنيات العلاقة بين المنسوب والتصريف","text":"اشرح لماذا يلزم تحديث منحنى التصريف بعد تغير واضح في مقطع النهر. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا يلزم تحديث منحنى التصريف بعد تغير واضح في مقطع النهر."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"الاستقراء خارج مجال القياسات يحمل عدم يقين مرتفعاً."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7920,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('reservoir-inflow-forecasting','التنبؤ بالتدفقات الداخلة إلى الخزانات','الهطول والحوض والتشغيل المائي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يدمج التنبؤ بالتدفق الداخل بيانات المطر والرطوبة والجريان المرصود ومخرجات النماذج، ثم يربطها بسيناريوهات تشغيل الخزان. يجب الفصل بين التوقع الطبيعي وقرارات التشغيل."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التنبؤ بالتدفقات الداخلة إلى الخزانات","text":"ضع مخططاً زمنياً لتحديث توقع التدفق الداخل أثناء عاصفة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع مخططاً زمنياً لتحديث توقع التدفق الداخل أثناء عاصفة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"يجب توثيق افتراضات التشغيل وعدم الخلط بينها وبين التنبؤ الجوي."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7930,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('flood-forecast-warning-chain','سلسلة التنبؤ بالفيضانات والتحذير','من الرصد إلى القرار والتواصل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتكون سلسلة الإنذار من جمع البيانات والتحليل والتنبؤ وتقييم الأثر وإصدار الرسالة ومتابعة التحديث. تتطلب حوكمة واضحة ومصادر موثوقة وتحديد مسؤوليات كل جهة."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"سلسلة التنبؤ بالفيضانات والتحذير","text":"صمم مخططاً يوضح انتقال المعلومة من محطة المطر إلى مركز التنبؤ ثم جهة الاستجابة. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مخططاً يوضح انتقال المعلومة من محطة المطر إلى مركز التنبؤ ثم جهة الاستجابة."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"التأخر في تبادل البيانات قد يقلل قيمة توقع صحيح علمياً."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7940,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات'),
('compound-flooding-coastal-river','الفيضانات المركبة الساحلية والنهرية','تزامن الجريان النهري والمد البحري والعواصف','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تتفاقم الفيضانات عندما يتزامن ارتفاع التصريف النهري مع المد أو ارتفاع مستوى البحر أو ضغط العاصفة. يتطلب التحليل ربط الحدود البحرية والنهرية وتوقيت الظواهر."},{"type":"heading","text":"الأساس الفيزيائي والهيدرولوجي"},{"type":"text","text":"يرتبط هذا الموضوع بحفظ الكتلة والطاقة وبالتغير المكاني والزماني للماء. يجب تحديد حجم التحكم والفترة الزمنية والحدود الداخلة والخارجة، ثم التمييز بين القياس المباشر والتقدير والنموذج. تختلف الاستجابة باختلاف خصائص السطح والحوض والظروف السابقة للحدث."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سلاسل زمنية للهطول وشدته وتوزيعه المكاني.","قياسات المنسوب والتصريف مع توثيق المعايرة.","خصائص الحوض والتربة والغطاء الأرضي والارتفاع.","حالة الرطوبة السابقة والظروف التشغيلية المؤثرة.","بيانات زمنية متزامنة مع فحص الفجوات والانحياز."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد السؤال التشغيلي والمقياس المكاني والزمني.","افحص جودة البيانات ووحداتها وتزامنها.","اختر الطريقة أو النموذج الملائم لمستوى البيانات.","قارن النتائج بقياسات مستقلة أو مصادر مرجعية.","وثق الافتراضات ومصادر عدم اليقين وحدود الاستخدام."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الفيضانات المركبة الساحلية والنهرية","text":"حلل سيناريو تزامن ذروة تصريف نهر مع مد مرتفع دون افتراض استقلال الحدثين. استخدم مجموعة بيانات افتراضية موثقة، واعرض خطوات التحليل والافتراضات والنتائج المتوقعة دون تقديمها كقياسات حقيقية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل سيناريو تزامن ذروة تصريف نهر مع مد مرتفع دون افتراض استقلال الحدثين."},{"type":"heading","text":"الأخطاء والقيود"},{"type":"callout","text":"تقييم كل مصدر منفرداً قد يقلل تقدير الخطر المركب."},{"type":"list","items":["خلط التقدير بالناتج المرصود مباشرة.","إهمال اختلاف المقياس المكاني أو الفترة الزمنية.","استخدام معاملات غير معايرة للبيئة المدروسة.","تجاهل القيم المفقودة والانحياز وعدم اليقين.","عرض توقع مفرد دون شرح نطاق الثقة والافتراضات."]},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعتمد التطبيق المهني لهذا الموضوع على تكامل الرصد الجوي والهيدرولوجي والتحليل المكاني والتحقق المستقل. وتزداد موثوقية القرار عندما تكون البيانات قابلة للتتبع والافتراضات معلنة وحدود التوقع واضحة."}]}'::jsonb,7950,55,'["شرح المفاهيم الفيزيائية والهيدرولوجية المرتبطة بالموضوع","اختيار البيانات والمنهجية المناسبة للتحليل","تقييم النتائج ومصادر عدم اليقين تطبيقياً"]'::jsonb,'النمذجة والرصد والتنبؤ بالفيضانات')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='الماء الجوي والتحول من المطر إلى الجريان' then u1.id else u2.id end,'الهيدرولوجيا الجوية والتنبؤ بالفيضانات',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;